contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint a, uint b, uint d) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a) + (b) + (d)); require(a <= 1000000000000000000000000000000); require(b <= 1000000000000000000000000000000); require(d <= 1000000000000000000000000000000);
        require(address(this).balance >= a + b + d);
        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint startBal = address(c).balance;
        c.deposit{value: b}(); if (__ESBMC_reverted()) return;
        c.deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint before = address(this).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        assert(address(this).balance == before + b + d && address(c).balance + b + d == startBal + b + d && address(c).balance == startBal);
    }
    receive() external payable {}
}

