// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a, uint256 b, uint256 d) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a + b + d);
        try c.deposit{value: a}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint startBal = address(c).balance;
        try c.deposit{value: b}() {} catch { return; }
        try c.deposit{value: d}() {} catch { return; }
        uint before = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        assertTrue(address(this).balance == before + b + d && address(c).balance + b + d == startBal + b + d && address(c).balance == startBal);
    }

    function testFuzz_run(uint256 a, uint256 b, uint256 d) public {
        _run(a, b, d);
    }

    receive() external payable {}
}
